/**
 * Cover Art Archive front artwork for metadata lookup (coverArtClient.ts front and lookupArtworkWebp) without any network: the
 * server-built URL and its redirect allowlist, the credential-free request path through the shared gate, SSRF refusals, byte and
 * pixel bounds, complete decoding, retries and the transient WebP preview. Every image is generated here; every name is synthetic.
 */
import assert from 'node:assert/strict';
import type { LookupAddress } from 'node:dns';
import { Readable } from 'node:stream';
import { after, test } from 'node:test';
import sharp from 'sharp';
import type { PinnedHttpsResponse, PinnedHttpsTransport } from '../../src/administration/adminPinnedHttps';
import {
    coverArtFrontDestination, coverArtFrontUrl, createCoverArtClient, lookupArtworkWebp, type CoverArtFrontSize, type LookupArtwork
} from '../../src/administration/lookup/coverArtClient';
import { MetadataLookupInputError, MetadataLookupSourceError, type LookupGateMode, type MetadataLookupSource } from '../../src/administration/lookup/lookupContract';
import type { MetadataLookupRateGate } from '../../src/administration/lookup/lookupRateGate';
import { createLookupResponseCache } from '../../src/administration/lookup/lookupResponseCache';
import type { LookupClientDependencies } from '../../src/administration/lookup/lookupSourceRequest';
import { availableLookupConfiguration, fixtureAddress, fixtureTransport, type LookupExchange } from '../support/metadataLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const mbid = '0000000c-0000-4000-8000-000000000001', otherMbid = '0000000c-0000-4000-8000-000000000002';
const front = (size: CoverArtFrontSize = 1200) => `https://coverartarchive.org/release/${mbid}/front-${size}`;
const caaImage = (size: CoverArtFrontSize = 1200, id = mbid) => `https://coverartarchive.org/release/${id}/12345-${size}.jpg`;
const download = (size: CoverArtFrontSize = 1200, id = mbid) => `https://archive.org/download/mbid-${id}/mbid-${id}-12345_thumb${size}.jpg`;
const storage = (size: CoverArtFrontSize = 1200, host = 'ia800505.us.archive.org', id = mbid) => `https://${host}/12/items/mbid-${id}/mbid-${id}-12345_thumb${size}.jpg`;
const redirect = (url: string, location: string, status = 302): LookupExchange => ({ url, status, headers: { location } });
const image = (url: string, bytes: Buffer, contentType = 'image/jpeg', headers: Record<string, string | null> = {}): LookupExchange =>
    ({ url, status: 200, headers: { 'content-type': contentType, ...headers }, bodyBase64: bytes.toString('base64') });
const solid = (width: number, height: number) => sharp({ create: { width, height, channels: 3, background: { r: 51, g: 102, b: 153 } } });

/** A gate that grants at once and records what the client asked of it. */
const recordingGate = () => {
    const record = { sources: [] as MetadataLookupSource[], modes: [] as LookupGateMode[], sends: 0, releases: 0 };
    const gate: MetadataLookupRateGate = { acquire: async (source, mode) => {
        record.sources.push(source); record.modes.push(mode);
        return { sent: () => { record.sends++; }, release: async () => { record.releases++; } };
    } };
    return { gate, record };
};
/** The real request path with a recording gate, cache and scheduler, an instant sleep and the synthetic operator contact. */
const client = (transport: PinnedHttpsTransport, overrides: Partial<LookupClientDependencies> = {}) => {
    const { gate, record } = recordingGate(), cache = createLookupResponseCache(), cached: string[] = [], scheduled: string[] = [], sleeps: number[] = [];
    const artwork = createCoverArtClient({ gate, transport, configuration: availableLookupConfiguration, sleep: async ms => { sleeps.push(ms); },
        cache: { get: key => cache.get(key), set: (key, value, bytes) => { cached.push(key); cache.set(key, value, bytes); }, clear: () => cache.clear() },
        schedule: (key, signal, operation) => { scheduled.push(key); return operation(); }, ...overrides });
    return { artwork, record, cached, scheduled, sleeps };
};
const fetchFront = (current: ReturnType<typeof client>, size: CoverArtFrontSize = 1200, mode: LookupGateMode = 'wait') =>
    current.artwork.front(mbid, size, { mode, signal: new AbortController().signal, clientKey: '0000000000000000000000a1' });
const failure = (kind: string) => (error: unknown) => {
    assert.ok(error instanceof MetadataLookupSourceError, String(error));
    assert.equal(error.source, 'coverartarchive'); assert.equal(error.failure, kind);
    return true;
};
let jpeg: Buffer;
const jpegBytes = async () => jpeg ??= await solid(64, 48).jpeg().toBuffer();

test('the front URL is built by the server, and only the same release\'s thumbnail of that size is allowed after a redirect', () => {
    assert.equal(coverArtFrontUrl(mbid, 1200).href, front(1200)); assert.equal(coverArtFrontUrl(mbid.toUpperCase(), 500).href, front(500));
    assert.throws(() => coverArtFrontUrl('not-an-mbid', 1200), MetadataLookupInputError);
    const allow = coverArtFrontDestination(mbid, 1200), allowed = (url: string, hop: number) => allow(new URL(url), hop)?.href ?? null;
    assert.equal(allowed(front(1200), 0), front(1200));
    for (const url of [caaImage(), download(), storage(), storage(1200, 'dn720003.ca.archive.org')]) {
        assert.equal(allowed(url, 0), null, `hop 0 is only the front URL: ${url}`); assert.equal(allowed(url, 1), url); assert.equal(allowed(url, 3), url);
    }
    for (const url of [front(500), `${front(1200)}?x=1`, `${download()}?`, `${download()}?a=b`, download(500), storage(500), caaImage(500), download(1200, otherMbid),
        storage(1200, 'ia800505.us.archive.org', otherMbid), caaImage(1200, otherMbid), storage(1200, 'evil.example'), storage(1200, 'ia800505.us.archive.org.evil.example'),
        'http://archive.org/download/x', download().replace('https://archive.org', 'http://archive.org'), download().replace('archive.org', 'archive.org:8443'),
        'https://93.184.216.34/download/x.jpg', `https://archive.org/details/mbid-${mbid}`, download().replace('.jpg', '.png'),
        `https://archive.org/download/mbid-${mbid}/index.json`, `https://user:secret@archive.org/download/mbid-${mbid}/mbid-${mbid}-1_thumb1200.jpg`]) {
        assert.equal(allowed(url, 1), null, url);
    }
});

test('the artwork follows at most three allowlisted hops with the contact User-Agent and only three headers, through the shared gate', async () => {
    const bytes = await jpegBytes();
    for (const chain of [[redirect(front(), download(), 307), redirect(download(), storage()), image(storage(), bytes)],
        [redirect(front(), caaImage(), 307), redirect(caaImage(), download()), redirect(download(), storage()), image(storage(), bytes)]]) {
        const fake = fixtureTransport(chain), current = client(fake.transport);
        const artwork = await fetchFront(current);
        assert.deepEqual(artwork, { bytes, contentType: 'image/jpeg', sha256: (await import('node:crypto')).createHash('sha256').update(bytes).digest('hex') });
        assert.deepEqual(fake.requests.map(request => request.url), chain.map(exchange => exchange.url));
        for (const request of fake.requests) assert.deepEqual({ ...request.headers }, { Accept: 'image/jpeg, image/png, image/webp', 'Accept-Encoding': 'identity', 'User-Agent': availableLookupConfiguration().userAgent });
        assert.deepEqual([current.record.sources, current.record.modes, current.record.sends, current.record.releases], [['coverartarchive'], ['wait'], chain.length, 1]);
        // Validation ran in the shared scheduler under the caller's key; nothing was cached.
        assert.deepEqual([current.scheduled, current.cached], [['0000000000000000000000a1'], []]);
    }
});

test('a private, loopback or link-local DNS answer at any hop, even one not selected, is refused before anything is sent', async () => {
    const bytes = await jpegBytes();
    for (const answers of [[{ address: '10.0.0.1', family: 4 }], [{ address: '127.0.0.1', family: 4 }], [{ address: '169.254.169.254', family: 4 }],
        [{ address: '::1', family: 6 }], [{ address: 'fe80::1', family: 6 }], [fixtureAddress, { address: '192.168.1.1', family: 4 }]] as LookupAddress[][]) {
        for (const hop of ['coverartarchive.org', 'archive.org']) {
            const fake = fixtureTransport([redirect(front(), download(), 307), redirect(download(), storage()), image(storage(), bytes)]);
            const transport: PinnedHttpsTransport = { ...fake.transport, lookup: async hostname => hostname === hop ? answers : [fixtureAddress] };
            const current = client(transport);
            await assert.rejects(fetchFront(current), failure('unavailable'), `${hop} ${JSON.stringify(answers)}`);
            assert.deepEqual(fake.requests.map(request => request.url), hop === 'coverartarchive.org' ? [] : [front()]);
        }
    }
});

test('a redirect to another host, scheme, release, size, port, query or an IP literal, a fourth redirect or a duplicate Location is refused unfollowed', async () => {
    const bytes = await jpegBytes();
    for (const location of ['https://example.org/download/x.jpg', download().replace('https:', 'http:'), download(1200, otherMbid), download(500), `${download()}?x=1`,
        'https://93.184.216.34/download/x.jpg', download().replace('archive.org', 'archive.org:8443'), `https://[2606:4700::1]/x.jpg`]) {
        const fake = fixtureTransport([redirect(front(), location, 307), image(location, bytes)]), current = client(fake.transport);
        await assert.rejects(fetchFront(current), failure('unavailable'), location);
        assert.deepEqual(fake.requests.map(request => request.url), [front()], location);
    }
    // A fourth redirect, even within the allowlist.
    const second = storage(1200, 'ia801234.us.archive.org');
    const long = fixtureTransport([redirect(front(), caaImage(), 307), redirect(caaImage(), download()), redirect(download(), storage()), redirect(storage(), second), image(second, bytes)]);
    await assert.rejects(fetchFront(client(long.transport)), failure('unavailable'));
    assert.equal(long.requests.length, 4);
    // Two Location headers, which Node would otherwise fold into one.
    let requests = 0;
    const duplicate: PinnedHttpsTransport = { lookup: async () => [fixtureAddress], request: async (): Promise<PinnedHttpsResponse> => {
        requests++;
        return { statusCode: 307, headers: { location: download() }, rawHeaders: ['Location', download(), 'Location', storage()], body: Readable.from([]) };
    } };
    await assert.rejects(fetchFront(client(duplicate)), failure('unavailable')); assert.equal(requests, 1);
});

test('oversized, pixel-bomb, undecodable, mistyped or encoded artwork is refused, and 404 is no artwork', async () => {
    const bytes = await jpegBytes(), png = await solid(32, 32).png().toBuffer();
    const bomb = await solid(5000, 4000).png({ compressionLevel: 9 }).toBuffer();
    assert.ok(bomb.length < 4 * 1024 * 1024, 'the bomb is small on the wire');
    const cases: [LookupExchange, string][] = [
        [image(front(), Buffer.alloc(16), 'image/jpeg', { 'content-length': String(4 * 1024 * 1024 + 1) }), 'unavailable'],
        [image(front(), Buffer.concat([bytes, Buffer.alloc(4 * 1024 * 1024)]), 'image/jpeg', { 'content-length': null }), 'unavailable'],
        [image(front(), bomb, 'image/png'), 'invalidResponse'],
        [image(front(), Buffer.concat([Buffer.from([0xff, 0xd8, 0xff, 0xe0]), Buffer.from('not really an image at all, just text'.repeat(4))])), 'invalidResponse'],
        [image(front(), bytes.subarray(0, bytes.length - 40)), 'invalidResponse'],
        [image(front(), png, 'image/jpeg'), 'invalidResponse'],
        [image(front(), bytes, 'image/gif'), 'invalidResponse'],
        [image(front(), bytes, 'text/html'), 'invalidResponse'],
        [image(front(), bytes, 'image/jpeg', { 'content-encoding': 'gzip' }), 'invalidResponse']
    ];
    for (const [exchange, kind] of cases) {
        const current = client(fixtureTransport([exchange]).transport);
        await assert.rejects(fetchFront(current), failure(kind), `${exchange.headers['content-type']} ${exchange.bodyBase64?.length}`);
        assert.deepEqual(current.cached, []);
    }
    // A PNG within the bounds is accepted with its own type.
    assert.equal((await fetchFront(client(fixtureTransport([image(front(), png, 'image/png')]).transport)))?.contentType, 'image/png');
    const missing = client(fixtureTransport([{ url: front(), status: 404, headers: { 'content-type': 'text/html' } }]).transport);
    assert.equal(await fetchFront(missing), null); assert.deepEqual([missing.cached, missing.scheduled], [[], []]);
    // Only the two sizes lookup uses can be requested.
    await assert.rejects(client(fixtureTransport([]).transport).artwork.front(mbid, 250 as CoverArtFrontSize, { mode: 'wait', signal: new AbortController().signal }), MetadataLookupInputError);
});

test('artwork larger than the thumbnail size it was asked for is refused, so a staged cover is never larger than 1200 px', async () => {
    const wide = await solid(3000, 2000).jpeg().toBuffer(), tall = await solid(10, 1201).png().toBuffer(), exact = await solid(1200, 800).jpeg().toBuffer();
    const cases: [CoverArtFrontSize, Buffer, string][] = [[1200, wide, 'image/jpeg'], [1200, tall, 'image/png'], [500, await solid(800, 600).jpeg().toBuffer(), 'image/jpeg'], [500, await solid(501, 501).webp().toBuffer(), 'image/webp']];
    for (const [size, bytes, contentType] of cases) {
        const current = client(fixtureTransport([image(front(size), bytes, contentType)]).transport);
        await assert.rejects(fetchFront(current, size), failure('invalidResponse'), `${size} ${contentType}`);
        assert.deepEqual(current.cached, []);
    }
    // A thumbnail exactly at its size, or smaller, is kept unchanged.
    const kept = await fetchFront(client(fixtureTransport([image(front(), exact)]).transport));
    assert.deepEqual([kept?.contentType, kept?.bytes.equals(exact)], ['image/jpeg', true]);
    assert.equal((await fetchFront(client(fixtureTransport([image(front(500), await solid(500, 333).jpeg().toBuffer())]).transport), 500))?.contentType, 'image/jpeg');
});

test('503 is retried in wait mode and rate limited after three attempts, busy mode tries once, unconfigured lookup sends nothing, and bytes are never cached', async () => {
    const bytes = await jpegBytes(), busyAnswer = (): LookupExchange => ({ url: front(), status: 503, headers: { 'content-type': 'text/html', 'retry-after': '1' } });
    const retried = client(fixtureTransport([busyAnswer(), image(front(), bytes)]).transport);
    assert.equal((await fetchFront(retried))?.contentType, 'image/jpeg'); assert.deepEqual([retried.record.sources.length, retried.sleeps], [2, [1000]]);
    const limited = client(fixtureTransport([busyAnswer(), busyAnswer(), busyAnswer()]).transport);
    await assert.rejects(fetchFront(limited), failure('rateLimited')); assert.equal(limited.record.sources.length, 3);
    const busy = client(fixtureTransport([busyAnswer()]).transport);
    await assert.rejects(fetchFront(busy, 1200, 'busy'), failure('rateLimited')); assert.equal(busy.record.sources.length, 1);
    const fake = fixtureTransport([]), unconfigured = client(fake.transport, { configuration: () => ({ available: false, reason: 'contactMissing' }) });
    await assert.rejects(fetchFront(unconfigured), failure('notConfigured'));
    assert.deepEqual([fake.lookups, fake.requests, unconfigured.record.sources], [[], [], []]);
    const twice = fixtureTransport([image(front(), bytes), image(front(), bytes)]), repeated = client(twice.transport);
    await fetchFront(repeated); await fetchFront(repeated);
    assert.deepEqual([twice.requests.length, repeated.cached], [2, []]);
});

test('a candidate preview is the front-500 thumbnail converted to WebP within 500 px, and undecodable bytes are refused', async () => {
    const thumbnail = await solid(500, 333).jpeg().toBuffer();
    const fake = fixtureTransport([redirect(front(500), download(500), 307), redirect(download(500), storage(500)), image(storage(500), thumbnail)]);
    const current = client(fake.transport), artwork = await fetchFront(current, 500);
    const scheduled: string[] = [];
    const preview = await lookupArtworkWebp(artwork!, new AbortController().signal, 'preview-key', (key, _signal, operation) => { scheduled.push(key); return operation(); });
    const metadata = await sharp(preview).metadata();
    assert.deepEqual([metadata.format, metadata.width, metadata.height, scheduled], ['webp', 500, 333, ['preview-key']]);
    // The conversion bounds any decoded artwork within 500 px on its own.
    const large = await lookupArtworkWebp({ bytes: await solid(1200, 800).jpeg().toBuffer(), contentType: 'image/jpeg', sha256: 'c'.repeat(64) }, new AbortController().signal, 'k');
    assert.deepEqual([(await sharp(large).metadata()).width, (await sharp(large).metadata()).height], [500, 333]);
    // A small image is never enlarged.
    const small = await lookupArtworkWebp({ bytes: await jpegBytes(), contentType: 'image/jpeg', sha256: 'a'.repeat(64) }, new AbortController().signal, 'k');
    assert.deepEqual([(await sharp(small).metadata()).width, (await sharp(small).metadata()).height], [64, 48]);
    const garbage: LookupArtwork = { bytes: Buffer.from([0xff, 0xd8, 0xff, 0xe0, 0, 1, 2, 3]), contentType: 'image/jpeg', sha256: 'b'.repeat(64) };
    await assert.rejects(lookupArtworkWebp(garbage, new AbortController().signal, 'k'), failure('invalidResponse'));
    const aborted = new AbortController(); aborted.abort();
    await assert.rejects(lookupArtworkWebp(artwork!, aborted.signal, 'k'), failure('cancelled'));
});
